def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]
    opp_def = sum(1 for a in opp if a == 'D')
    opp_c = n - opp_def

    if opp_def == 0:
        return 'C'
    if opp_c == 0:
        return 'D'

    if n > 90 and last_opp == 'D':
        return 'D'

    recent_len = min(10, n)
    recent = opp[-recent_len:]
    recent_c = sum(1 for a in recent if a == 'C')
    recent_ratio = recent_c / recent_len

    if recent_len >= 6:
        last6 = opp[-6:]
        if all(a == 'D' for a in last6):
            return 'D'
        if all(a == 'C' for a in last6):
            return 'C'

    if last_opp == 'D':
        if last_me == 'C':
            if recent_ratio > 0.6:
                return 'C'
            else:
                return 'D'
        else:
            if recent_ratio > 0.35:
                return 'C'
            else:
                return 'D'
    else:
        if len(history) >= 3:
            last3 = opp[-3:]
            if last3 == ['C', 'C', 'D'] and last_me == 'C':
                return 'D'
        return 'C'
